              <circle cx={KEY.cx} cy={KEY.cy} r="15" fill="url(#ign-ring)" />
              <circle cx={KEY.cx} cy={KEY.cy} r="15" fill="none" stroke="#000" strokeOpacity="0.5" />
              <path d={`M${KEY.cx - 9} ${KEY.cy - 2} L${KEY.cx - 22} ${KEY.cy - 40} Q${KEY.cx - 26} ${KEY.cy - 82} ${KEY.cx} ${KEY.cy - 86} Q${KEY.cx + 26} ${KEY.cy - 82} ${KEY.cx + 22} ${KEY.cy - 40} L${KEY.cx + 9} ${KEY.cy - 2} Z`} fill="#000" opacity="0.5" transform="translate(3 5)" filter="url(#ign-blur4)" />
              <path d={`M${KEY.cx - 9} ${KEY.cy - 2} L${KEY.cx - 22} ${KEY.cy - 40} Q${KEY.cx - 26} ${KEY.cy - 82} ${KEY.cx} ${KEY.cy - 86} Q${KEY.cx + 26} ${KEY.cy - 82} ${KEY.cx + 22} ${KEY.cy - 40} L${KEY.cx + 9} ${KEY.cy - 2} Z`} fill="url(#ign-keyhead)" stroke="#000" strokeWidth="1" />
              {[0, 1, 2, 3, 4].map((i) => (
                <path key={i} d={`M${KEY.cx - 15 + i * 0.6} ${KEY.cy - 30 - i * 5} L${KEY.cx + 15 - i * 0.6} ${KEY.cy - 30 - i * 5}`} stroke="#000" strokeOpacity="0.6" strokeWidth="1.4" />
              ))}
              <path d={`M${KEY.cx - 15} ${KEY.cy - 72} Q${KEY.cx} ${KEY.cy - 85} ${KEY.cx + 15} ${KEY.cy - 72}`} stroke="#fff" strokeOpacity="0.2" strokeWidth="2" fill="none" />
              <text x={KEY.cx} y={KEY.cy - 50} fill="url(#ign-badge)" fontSize="8" fontWeight="800" fontStyle="italic" textAnchor="middle" letterSpacing="1">AMGT</text>
              <circle cx={KEY.cx} cy={KEY.cy - 64} r="5" fill="#020202" stroke="#2c2d31" />
            </g>
          </g>
          {/* keyring + leather fob, swinging under gravity */}
          <g ref={ringRef} pointerEvents="none" transform={`translate(${KEY.cx} ${KEY.cy - 64})`}>
            <circle cx="0" cy="13" r="13" fill="none" stroke="url(#ign-ring)" strokeWidth="2.8" />
            <rect x="-4" y="24" width="8" height="9" rx="2" fill="url(#ign-alu)" />
            <path d="M-13 33 L13 33 L15 78 Q0 88 -15 78 Z" fill="#3a2418" stroke="#1d120b" strokeWidth="1" />
            <path d="M-13 33 L13 33 L15 78 Q0 88 -15 78 Z" fill="#fff" filter="url(#ign-leather)" />
            <path d="M-10 37 L10 37 L11 74 Q0 81 -11 74 Z" fill="none" stroke="#c7a27a" strokeOpacity="0.5" strokeWidth="0.9" strokeDasharray="2.2 1.8" />
            <text x="0" y="58" fill="#c7a27a" fillOpacity="0.55" fontSize="7" fontWeight="700" textAnchor="middle" letterSpacing="0.5">AMGT</text>
          </g>
        </svg>
      </div>

      <div className="pointer-events-none absolute right-0 top-0 flex flex-col items-end p-5 text-right text-[13px] leading-relaxed text-white/70">
        {phase === "run" ? (
          <>
            <span>Hold Space or the windshield to rev</span>
            <span>Tap the key to switch off</span>
            <span>Press the wheel center for the horn</span>
          </>
        ) : (
          <>
            <span>Press and hold the key to start</span>
            <span>Keep holding until the engine catches</span>
            <span>Press the wheel center for the horn</span>
          </>
        )}
      </div>
      {children && <div className="absolute inset-x-0 bottom-0 flex justify-center p-4">{children}</div>}
    </div>
  );
}

